import logoImage from "~/assets/images/logo/Creaova_Logo1-transparent.png";

/**
 * The brand lockup: mark + wordmark, raster, generated by
 * scripts/prepare-logo.ps1 from logo/Creaova_Logo1.png.
 *
 * Three things this component is responsible for:
 *
 * 1. **Intrinsic dimensions are always present.** Without them the header
 *    reflows the moment the image decodes. They must stay in sync with the real
 *    file — hence they live in lib/site.ts next to the path.
 *
 * 2. **`alt` defaults to empty, deliberately.** In the navbar this sits inside a
 *    link that is already labelled "Creaova — home". Giving the image
 *    alt="Creaova" as well makes a screen reader announce the brand twice for
 *    one link. Pass an explicit `alt` only where the image carries the meaning
 *    on its own (the footer lockup).
 *
 * 3. **`variant` picks the surface.** The artwork is orange-on-white, so on the
 *    dark footer band the ink wordmark would disappear against #111111. The
 *    inverse variant is flat white, which is the only treatment guaranteed to
 *    read there (see the reasoning in scripts/prepare-logo.ps1).
 */
export function Logo({
  variant: _variant = "ink",
  alt = "",
  priority = false,
  className = "h-11 md:h-12",
}: {
  variant?: "ink" | "inverse";
  alt?: string;
  /** Above-the-fold only: opts out of lazy loading and raises fetch priority. */
  priority?: boolean;
  className?: string;
}) {
  return (
    <img
      src={logoImage}
      alt={alt}
      width={1254}
      height={1254}
      decoding="async"
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      className={`w-auto ${className}`}
    />
  );
}
